# /etc/nginx/nginx.conf — struktur minimal
user  www-data;
worker_processes  auto;          # 1 worker per CPU core
pid   /run/nginx.pid;

# Mekanisme event: seberapa efisien worker menangani koneksi
events {
    worker_connections  1024;    # maks koneksi per worker
    use epoll;                    # event method tercepat di Linux
    multi_accept on;              # terima banyak koneksi sekaligus
}

http {
    include       /etc/nginx/mime.types;
    default_type  application/octet-stream;
    sendfile      on;             # kirim file statis langsung dari kernel
    keepalive_timeout 65;
    include /etc/nginx/conf.d/*.conf;
    include /etc/nginx/sites-enabled/*;
}

# /etc/nginx/sites-available/app.conf
upstream app_backend {
    least_conn;                    # kirim ke server dengan koneksi paling sedikit
    server 127.0.0.1:3000;
    server 127.0.0.1:3001;
    keepalive 32;
}

server {
    listen 80;
    server_name app.example.id;
    return 301 https://$host$request_uri;  # paksa HTTPS
}

server {
    listen 443 ssl http2;
    server_name app.example.id;

    ssl_certificate     /etc/letsencrypt/live/app.example.id/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/app.example.id/privkey.pem;

    # Kompresi: hemat bandwidth untuk teks
    gzip on;
    gzip_types text/plain text/css application/json application/javascript;
    gzip_min_length 1024;

    # Aset statis: cache 30 hari di browser
    location /static/ {
        alias /var/www/app/static/;
        expires 30d;
        add_header Cache-Control "public, immutable";
    }

    # API: teruskan ke backend, sertakan header asli client
    location /api/ {
        proxy_pass http://app_backend;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }

    # SPA fallback: semua route lain ke index.html
    location / {
        try_files $uri $uri/ /index.html;
    }
}
